export function hasCustomProjectIcon(name: string): boolean {
  return Object.prototype.hasOwnProperty.call(CUSTOM_ENTITY_ICONS, name);
}

export function CustomProjectIcon(props: {
  name: string;
  size?: number;
  className?: string;
  style?: CSSProperties;
}) {
  const { name, size = 16, className, style } = props;
  const def = CUSTOM_ENTITY_ICONS[name];
  if (!def) return null;
  return (
    <svg
      width={size}
      height={size}
      viewBox={def.viewBox}
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      aria-hidden="true"
      {...(className != null ? { className } : {})}
      {...(style != null ? { style } : {})}
    >
      {def.paths.map((path, index) => (
        <path
          key={index}
          d={path.d}
          fill="currentColor"
          {...(path.fillRule != null ? { fillRule: path.fillRule } : {})}
        />
      ))}
    </svg>
  );
}
